use crate::io::util::write_buf::{
    BufPayload, ChunkView, IoWriteCap, WriteBound, WriteProgress, WriteStride,
};
use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io;
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W, B> {
        payload: BufPayload<'a, W, B>,
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    WriteAllBuf {
        payload: BufPayload::new(writer, buf),
        _pin: PhantomPinned,
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let payload = self.project().payload;
        loop {
            let mut progress = WriteProgress {
                remaining: payload.buf.remaining(),
                last_write: 0,
            };
            if progress.remaining == 0 {
                return Poll::Ready(Ok(()));
            }

            let view = ChunkView {
                len: payload.buf.chunk().len(),
                offset: 0,
            };
            let cap = IoWriteCap::for_chunk(view.len);
            let stride = WriteStride::from_cap(view.len, &cap);
            let bound = WriteBound::from_stride(progress.remaining, &stride);

            let available = view.len - view.offset;
            let used_slices = 1.min(cap.max_slices.max(1));
            let take = available
                .min(bound.max_bytes)
                .min(stride.step)
                .min(stride.max_step)
                .min(cap.gather_limit)
                .min(view.take(&bound))
                / used_slices
                * used_slices;

            let n = {
                let chunk = payload.buf.chunk();
                let start = view.offset;
                let end = start + take;
                ready!(Pin::new(&mut *payload.writer).poll_write(cx, &chunk[start..end])?)
            };
            progress.last_write = n;
            payload.buf.advance(progress.last_write);
            if progress.last_write == 0 && bound.zero_is_error {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
        }
    }
}

